body.query:
query summary($q: String, $predicate: Predicate,  $size: Int, $from: Int){
  search: occurrenceSearch(q: $q, predicate: $predicate) {
    documents(size: 0) {
      total
    }
    cardinality {
      total: datasetKey
    }
    facet {
      results: datasetKey(size: $size, from: $from) {
        key
        count
        entity: dataset {title}
        occurrences {
          metaPredicate
          _meta
        }
      }
    }
  }

}
